24	
25	bool operator==(const Calibration::CalType &lhs, const Calibration::CalType &rhs) {
26	    if(lhs.type != rhs.type) {
27	        return false;
28	    }
29	    if(lhs.usedPorts.size() != rhs.usedPorts.size()) {
30	        return false;
31	    }
32	    for(unsigned int i=0;i<lhs.usedPorts.size();i++) {
33	        if(lhs.usedPorts[i] != rhs.usedPorts[i]) {
34	            return false;
35	        }
36	    }
37	    // all fields are equal
38	    return true;
39	}
40	
41	Calibration::Calibration()
42	    : SCPINode("CALibration")
43	{
44	    caltype.type = Type::None;
45	    unsavedChanges = false;
46	
47	    // create SCPI commands
48	    add(new SCPICommand("ACTivate", [=](QStringList params) -> QString {
49	        if(params.size() != 1) {
50	            return SCPI::getResultName(SCPI::Result::Error);
51	        } else {
52	            auto availableCals = getAvailableCalibrations();
53	            for(auto caltype : availableCals) {
54	                if(caltype.getShortString().compare(params[0], Qt::CaseInsensitive) == 0) {
55	                    // found a match
56	                    // check if calibration can be activated
57	                    if(canCompute(caltype)) {
58	                        compute(caltype);
59	                        return SCPI::getResultName(SCPI::Result::Empty);
60	                    } else {
61	                        return SCPI::getResultName(SCPI::Result::Error);
62	                    }
63	                }
64	            }
65	            // if we get here, the supplied parameter did not match any of the available calibrations
66	            return SCPI::getResultName(SCPI::Result::Error);
67	        }
68	        return SCPI::getResultName(SCPI::Result::Empty);
69	    }, [=](QStringList) -> QString {
70	        auto availableCals = getAvailableCalibrations();
71	        if(availableCals.size() == 0) {
72	            return SCPI::getResultName(SCPI::Result::Empty);
73	        }
74	        auto ret = availableCals[0].getShortString();
75	        for(unsigned int i=1;i<availableCals.size();i++) {
76	            ret += ",";
77	            ret += availableCals[i].getShortString();
78	        }
79	        return ret;
80	    }));
81	    add(new SCPICommand("ACTIVE", nullptr, [=](QStringList) -> QString {
82	        return caltype.getShortString();
83	    }));
84	    add(new SCPICommand("NUMber", nullptr, [=](QStringList) -> QString {
85	        return QString::number(measurements.size());
86	    }));
87	    add(new SCPICommand("RESET", [=](QStringList) -> QString {
88	        reset();
89	        return SCPI::getResultName(SCPI::Result::Empty);
90	    }, nullptr));
91	    add(new SCPICommand("ADD", [=](QStringList params) -> QString {
92	        if(params.size() < 1) {
93	            // no measurement type specified
94	            return SCPI::getResultName(SCPI::Result::Error);
95	        } else {
96	            // parse measurement type
97	            auto type = CalibrationMeasurement::Base::TypeFromString(params[0]);
98	            auto newMeas = newMeasurement(type);
99	            if(!newMeas) {
100	                // failed to create this type of measurement
101	                return SCPI::getResultName(SCPI::Result::Error);
102	            }
103	            if(params.size() == 2) {
104	                // standard name given
105	                CalStandard::Virtual *standard = nullptr;
106	                for(auto s : newMeas->supportedStandards()) {
107	                    if(s->getName().compare(params[1], Qt::CaseInsensitive) == 0) {
108	                        // use this standard
109	                        standard = s;
110	                    }
111	                }
112	                if(!standard) {
113	                    // specified standard not available
114	                    return SCPI::getResultName(SCPI::Result::Error);
115	                }
116	                newMeas->setStandard(standard);
117	            }
118	            measurements.push_back(newMeas);
119	            return SCPI::getResultName(SCPI::Result::Empty);
120	        }
121	    }, nullptr));
122	    add(new SCPICommand("TYPE", nullptr, [=](QStringList params) -> QString {
123	        if(params.size() < 1) {
124	            // no measurement number specified
125	            return SCPI::getResultName(SCPI::Result::Error);
126	        } else {
127	            bool okay;
128	            unsigned int number = params[0].toUInt(&okay);
129	            if(!okay || number >= measurements.size()) {
130	                // invalid measurement specified
131	                return SCPI::getResultName(SCPI::Result::Error);
132	            }
133	            return CalibrationMeasurement::Base::TypeToString(measurements[number]->getType());
134	        }
135	    }));
136	    add(new SCPICommand("PORT", [=](QStringList params) -> QString {
137	        if(params.size() < 1) {
138	            // invalid number of parameters
139	            return SCPI::getResultName(SCPI::Result::Error);
140	        } else {
141	            bool okay;
142	            unsigned int number = params[0].toUInt(&okay);
143	            if(!okay || number >= measurements.size()) {
144	                // invalid measurement specified
145	                return SCPI::getResultName(SCPI::Result::Error);
146	            }
147	            auto meas = measurements[number];
148	            auto onePort = dynamic_cast<CalibrationMeasurement::OnePort*>(meas);
149	            if(onePort) {
150	                if(params.size() != 2) {
151	                    // invalid number of parameters
152	                    return SCPI::getResultName(SCPI::Result::Error);
153	                }
154	                bool okay;
155	                unsigned int number = params[1].toInt(&okay);
156	                if(!okay || number < 1 || number > DeviceDriver::getInfo(DeviceDriver::getActiveDriver()).Limits.VNA.ports) {
157	                    // invalid port specified
158	                    return SCPI::getResultName(SCPI::Result::Error);
159	                }
160	                onePort->setPort(number);
161	                return SCPI::getResultName(SCPI::Result::Empty);
162	            }
163	            auto twoPort = dynamic_cast<CalibrationMeasurement::TwoPort*>(meas);
164	            if(twoPort) {
165	                if(params.size() != 3) {
166	                    // invalid number of parameters
167	                    return SCPI::getResultName(SCPI::Result::Error);
168	                }
169	                bool okay1;
170	                unsigned int port1 = params[1].toInt(&okay1);
171	                bool okay2;
172	                unsigned int port2 = params[2].toInt(&okay2);
173	                if(!okay1 || !okay2 || port1 < 1 || port2 > DeviceDriver::getInfo(DeviceDriver::getActiveDriver()).Limits.VNA.ports
174	                         || port2 < 1 || port2 > DeviceDriver::getInfo(DeviceDriver::getActiveDriver()).Limits.VNA.ports) {
175	                    // invalid port specified
176	                    return SCPI::getResultName(SCPI::Result::Error);
177	                }
178	                twoPort->setPort1(port1);
179	                twoPort->setPort2(port2);
180	                return SCPI::getResultName(SCPI::Result::Empty);
181	            }
182	            return SCPI::getResultName(SCPI::Result::Error);
183	        }
184	    }, [=](QStringList params) -> QString {
185	        if(params.size() != 1) {
186	            // invalid number of parameters
187	            return SCPI::getResultName(SCPI::Result::Error);
188	        } else {
189	            bool okay;
190	            unsigned int number = params[0].toUInt(&okay);
191	            if(!okay || number >= measurements.size()) {
192	                // invalid measurement specified
193	                return SCPI::getResultName(SCPI::Result::Error);
194	            }
195	            auto meas = measurements[number];
196	            auto onePort = dynamic_cast<CalibrationMeasurement::OnePort*>(meas);
197	            if(onePort) {
198	                return QString::number(onePort->getPort());
199	            }
200	            auto twoPort = dynamic_cast<CalibrationMeasurement::TwoPort*>(meas);
201	            if(twoPort) {
202	                return QString::number(twoPort->getPort1()) + " " + QString::number(twoPort->getPort2());
203	            }
204	            return SCPI::getResultName(SCPI::Result::Error);
205	        }
206	    }));
207	    add(new SCPICommand("STANDARD", [=](QStringList params) -> QString {
208	        if(params.size() != 2) {
209	            // invalid number of parameters
210	            return SCPI::getResultName(SCPI::Result::Error);
211	        } else {
212	            bool okay;
213	            unsigned int number = params[0].toUInt(&okay);
214	            if(!okay || number >= measurements.size()) {
215	                // invalid measurement specified
216	                return SCPI::getResultName(SCPI::Result::Error);
217	            }
218	            auto meas = measurements[number];
219	            for(auto s : meas->supportedStandards()) {
220	                if(s->getName().compare(params[1], Qt::CaseInsensitive) == 0) {
221	                    // use this standard
222	                    meas->setStandard(s);
223	                    return SCPI::getResultName(SCPI::Result::Empty);
224	                }
225	            }
226	            // specified standard not available
227	            return SCPI::getResultName(SCPI::Result::Error);
228	        }
229	    }, [=](QStringList params) -> QString {
230	        if(params.size() != 1) {
231	            // invalid number of parameters
232	            return SCPI::getResultName(SCPI::Result::Error);
233	        } else {
234	            bool okay;
235	            unsigned int number = params[0].toUInt(&okay);
236	            if(!okay || number >= measurements.size()) {
237	                // invalid measurement specified
238	                return SCPI::getResultName(SCPI::Result::Error);
239	            }
240	            auto s = measurements[number]->getStandard();
241	            if(s) {
242	                return s->getName();
243	            } else {
244	                // no standard set
245	                return "None";
246	            }
247	        }
248	    }));
249	    add(new SCPICommand("MEASure", [=](QStringList params) -> QString {
250	        if(params.size() < 1 ) {
251	            // no measurement specified
252	            // TODO check if measurement is already running
253	            return SCPI::getResultName(SCPI::Result::Error);
254	        } else {
255	            // assemble list of measurements to take
256	            std::set<CalibrationMeasurement::Base*> m;
257	            for(QString p : params) {
258	                bool okay = false;
259	                unsigned int number = p.toUInt(&okay);
260	                if(!okay || number >= measurements.size()) {
261	                    // invalid measurement specified
262	                    return SCPI::getResultName(SCPI::Result::Error);
263	                } else {
264	                    m.insert(measurements[number]);
265	                }
266	            }
267	            if(CalibrationMeasurement::Base::canMeasureSimultaneously(m)) {
