346	            return lhs.frequency < rhs;
347	        });
348	        auto highPoint = *lower;
349	        auto lowPoint = *prev(lower);
350	        double alpha = (d.frequency - lowPoint.frequency) / (highPoint.frequency - lowPoint.frequency);
351	
352	        p = lowPoint.interpolate(highPoint, alpha);
353	    }
354	
355	    // Grab measurements (easier to access by index later)
356	    for(unsigned int i=0;i<caltype.usedPorts.size();i++) {
