374	    // assemble a (L) and b (K) matrices
375	    for(unsigned int i=0;i<caltype.usedPorts.size();i++) {
376	        for(unsigned int j=0;j<caltype.usedPorts.size();j++) {
377	            if(i == j) {
378	                // calculate incident and reflected wave at the exciting port
379	                a(j,i) = 1.0 + p.S[i]/p.R[i]*(S(j,i) - p.D[i]*1.0);
380	                b(j,i) = (1.0 / p.R[i]) * (S(j,i) - p.D[i]*1.0);
