748	Calibration::Point Calibration::createInitializedPoint(double f) {
749	    Point point;
750	    point.frequency = f;
751	    // resize vectors
752	    point.D.resize(caltype.usedPorts.size(), 0.0);
753	    point.R.resize(caltype.usedPorts.size(), 1.0);
754	    point.S.resize(caltype.usedPorts.size(), 0.0);
755	
756	    point.L.resize(caltype.usedPorts.size());
757	    point.T.resize(caltype.usedPorts.size());
758	    point.I.resize(caltype.usedPorts.size());
759	    fill(point.L.begin(), point.L.end(), vector<complex<double>>(caltype.usedPorts.size(), 0.0));
760	    fill(point.T.begin(), point.T.end(), vector<complex<double>>(caltype.usedPorts.size(), 1.0));
761	    fill(point.I.begin(), point.I.end(), vector<complex<double>>(caltype.usedPorts.size(), 0.0));
762	    return point;
763	}
764	
765	Calibration::Point Calibration::computeOSL(double f)
766	{
767	    Point point = createInitializedPoint(f);
768	
769	    // Calculate SOL coefficients
770	    for(unsigned int i=0;i<caltype.usedPorts.size();i++) {
771	        auto p = caltype.usedPorts[i];
772	        auto _short = static_cast<CalibrationMeasurement::Short*>(findMeasurement(CalibrationMeasurement::Base::Type::Short, p));
773	        auto open = static_cast<CalibrationMeasurement::Open*>(findMeasurement(CalibrationMeasurement::Base::Type::Open, p));
774	        auto s_m = _short->getMeasured(f);
775	        auto o_m = open->getMeasured(f);
776	        auto s_c = _short->getActual(f);
777	        auto o_c = open->getActual(f);
778	        complex<double> l_c, l_m;
779	        auto slidingMeasurements = findMeasurements(CalibrationMeasurement::Base::Type::SlidingLoad, p);
780	        if(slidingMeasurements.size() >= 3) {
781	            // use sliding load
782	            vector<complex<double>> slidingMeasured;
783	            for(auto m : slidingMeasurements) {
784	                auto slidingLoad = static_cast<CalibrationMeasurement::SlidingLoad*>(m);
785	                auto value = slidingLoad->getMeasured(f);
786	                if(isnan(abs(value))) {
787	                    throw runtime_error("missing sliding load measurement");
788	                }
789	                slidingMeasured.push_back(value);
790	            }
791	            // use center of measurement for ideal load measurement
792	            l_m = Util::findCenterOfCircle(slidingMeasured);
793	            // assume perfect sliding load
794	            l_c = 0.0;
795	        } else {
796	            // use normal load standard
797	            auto load = static_cast<CalibrationMeasurement::Load*>(findMeasurement(CalibrationMeasurement::Base::Type::Load, p));
798	            l_c = load->getActual(f);
799	            l_m = load->getMeasured(f);
800	        }
801	        auto denom = l_c * o_c * (o_m - l_m) + l_c * s_c * (l_m - s_m) + o_c * s_c * (s_m - o_m);
802	        point.D[i] = (l_c * o_m * (s_m * (o_c - s_c) + l_m * s_c) - l_c * o_c * l_m * s_m + o_c * l_m * s_c * (s_m - o_m)) / denom;
803	        point.S[i] = (l_c * (o_m - s_m) + o_c * (s_m - l_m) + s_c * (l_m - o_m)) / denom;
804	        auto delta = (l_c * l_m * (o_m - s_m) + o_c * o_m * (s_m - l_m) + s_c * s_m * (l_m - o_m)) / denom;
805	        point.R[i] = point.D[i] * point.S[i] - delta;
806	    }
807	    return point;
