905	Calibration::Point Calibration::computeTRL(double freq)
906	{
907	    Point point = createInitializedPoint(freq);
908	
909	    // calculate forward match and transmission
910	    for(unsigned int i=0;i<caltype.usedPorts.size();i++) {
911	        for(unsigned int j=0;j<caltype.usedPorts.size();j++) {
912	            if(i == j) {
913	                // calculation only possible with through measurements
914	                continue;
915	            }
916	            auto p1 = caltype.usedPorts[i];
917	            auto p2 = caltype.usedPorts[j];
918	            // grab reflection measurements
919	            auto S11_reflection = static_cast<CalibrationMeasurement::Reflect*>(findMeasurement(CalibrationMeasurement::Base::Type::Reflect, p1));
920	            auto S22_reflection = static_cast<CalibrationMeasurement::Reflect*>(findMeasurement(CalibrationMeasurement::Base::Type::Reflect, p2));
921	            bool S11_short, S22_short;
922	            {
923	                auto S11_short_standard = dynamic_cast<CalStandard::Short*>(S11_reflection->getStandard());
924	                auto S11_open_standard = dynamic_cast<CalStandard::Open*>(S11_reflection->getStandard());
925	                auto S11_reflect_standard = dynamic_cast<CalStandard::Reflect*>(S11_reflection->getStandard());
926	                if(S11_short_standard) {
927	                    S11_short = true;
928	                } else if(S11_open_standard) {
929	                    S11_short = false;
930	                } else if(S11_reflect_standard) {
931	                    S11_short = S11_reflect_standard->getIsShort();
932	                } else {
933	                    // invalid standard
934	                    throw runtime_error("Invalid standard defined for reflection measurement");
935	                }
936	                auto S22_short_standard = dynamic_cast<CalStandard::Short*>(S22_reflection->getStandard());
937	                auto S22_open_standard = dynamic_cast<CalStandard::Open*>(S22_reflection->getStandard());
938	                auto S22_reflect_standard = dynamic_cast<CalStandard::Reflect*>(S22_reflection->getStandard());
939	                if(S22_short_standard) {
940	                    S22_short = true;
941	                } else if(S22_open_standard) {
942	                    S22_short = false;
943	                } else if(S22_reflect_standard) {
944	                    S22_short = S22_reflect_standard->getIsShort();
945	                } else {
946	                    // invalid standard
947	                    throw runtime_error("Invalid standard defined for reflection measurement");
948	                }
949	            }
950	            bool reflectionIsNegative;
951	            if(S11_short && S22_short) {
952	                reflectionIsNegative = true;
953	            } else if(!S11_short && !S22_short) {
954	                reflectionIsNegative = false;
955	            } else {
956	                throw runtime_error("Reflection measurements must all use the same standard (either open or short)");
957	            }
958	            // grab through measurement
959	            auto throughForward = static_cast<CalibrationMeasurement::Through*>(findMeasurement(CalibrationMeasurement::Base::Type::Through, p1, p2));
960	            auto throughReverse = static_cast<CalibrationMeasurement::Through*>(findMeasurement(CalibrationMeasurement::Base::Type::Through, p2, p1));
961	            Sparam Sthrough;
962	            if(throughForward) {
963	                Sthrough = throughForward->getMeasured(freq);
964	            } else if(throughReverse) {
965	                Sthrough = throughReverse->getMeasured(freq);
966	                Sthrough.swapPorts(1,2);
967	            }
968	            // grab line measurement
969	            auto forwardLines = findMeasurements(CalibrationMeasurement::Base::Type::Line, p1, p2);
970	            auto reverseLines = findMeasurements(CalibrationMeasurement::Base::Type::Line, p2, p1);
971	            // find the closest (geometric) match for the current frequency
972	            double closestIdealFreqRatio = numeric_limits<double>::max();
973	            bool closestLineIsReversed = false;
974	            CalibrationMeasurement::Line* closestLine = nullptr;
975	            CalStandard::Line* closestStandard = nullptr;
976	            for(int i=0;i<2;i++) {
977	                auto list = i ? reverseLines : forwardLines;
978	                for(auto l : list) {
979	                    auto line = static_cast<CalibrationMeasurement::Line*>(l);
980	                    auto standard = static_cast<CalStandard::Line*>(line->getStandard());
981	                    double idealFreq = (standard->minFrequency() + standard->maxFrequency()) / 2;
982	                    double mismatch = idealFreq / freq;
983	                    if(mismatch < 0) {
984	                        mismatch = 1.0 / mismatch;
985	                    }
986	                    if(mismatch < closestIdealFreqRatio) {
987	                        closestIdealFreqRatio = mismatch;
988	                        closestLineIsReversed = i > 0;
989	                        closestLine = line;
990	                        closestStandard = standard;
991	                    }
992	                }
993	            }
994	            if(!closestLine) {
995	                throw runtime_error("Unable to find required line measurement");
996	            }
997	            if(freq < closestStandard->minFrequency() || freq > closestStandard->maxFrequency()) {
998	                throw runtime_error("No line standard supports the required frequency ("+QString::number(freq).toStdString()+")");
999	            }
1000	
1001	            Sparam Sline = closestLine->getMeasured(freq);
1002	            if(closestLineIsReversed) {
1003	                Sline.swapPorts(1,2);
1004	            }
1005	
1006	            // got all required measurements
1007	            // calculate TRL calibration
1008	            // variable names and formulas according to http://emlab.uiuc.edu/ece451/notes/new_TRL.pdf
1009	            // page 19
1010	            auto R_T = Tparam(Sthrough);
1011	            auto R_D = Tparam(Sline);
1012	            auto T = R_D*R_T.inverse();
1013	            complex<double> a_over_c, b;
1014	            // page 21-22
1015	            Util::solveQuadratic(T.get(2,1), T.get(2,2) - T.get(1,1), -T.get(1,2), b, a_over_c);
1016	            // ensure correct root selection
1017	            // page 23
1018	            if(abs(b) >= abs(a_over_c)) {
1019	                swap(b, a_over_c);
1020	            }
1021	            // page 24
1022	            auto g = R_T.get(2,2);
1023	            auto d = R_T.get(1,1) / g;
1024	            auto e = R_T.get(1,2) / g;
1025	            auto f = R_T.get(2,1) / g;
1026	
1027	            // page 25
1028	            auto r22_rho22 = g * (1.0 - e / a_over_c) / (1.0 - b / a_over_c);
1029	            auto gamma = (f - d / a_over_c) / (1.0 - e / a_over_c);
1030	            auto beta_over_alpha = (e - b) / (d - b * f);
1031	            // page 26
1032	            auto alpha_a = (d - b * f) / (1.0 - e / a_over_c);
1033	            auto w1 = S11_reflection->getMeasured(freq);
1034	            auto w2 = S22_reflection->getMeasured(freq);
1035	            // page 28
1036	            auto a = sqrt((w1 - b) / (w2 + gamma) * (1.0 + w2 * beta_over_alpha) / (1.0 - w1 / a_over_c) * alpha_a);
1037	            // page 29, check sign of a
1038	            auto reflection = (w1 - b) / (a * (1.0 - w1 / a_over_c));
1039	            if((reflection.real() > 0 && reflectionIsNegative) || (reflection.real() < 0 && !reflectionIsNegative)) {
1040	                // wrong sign for a
1041	                a = -a;
1042	            }
1043	            // Revert back from error boxes with T parameters to S paramaters,
1044	            // page 17 + formulas for calculating S parameters from T parameters.
1045	            // Forward coefficients, normalize for S21 = 1.0 -> r22 = 1.0
1046	            auto r22 = complex<double>(1.0);
1047	            auto rho22 = r22_rho22 / r22;
1048	            auto alpha = alpha_a / a;
1049	            auto beta = beta_over_alpha * alpha;
1050	            auto c = a / a_over_c;
1051	            auto Box_A = Tparam(r22 * a, r22 * b, r22 * c, r22);
1052	            auto Box_B = Tparam(rho22 * alpha, rho22 * beta, rho22 * gamma, rho22);
1053	            auto S_A = Sparam(Box_A);
1054	            point.D[i] = S_A.get(1,1);
1055	            point.R[i] = S_A.get(1,2);
1056	            point.S[i] = S_A.get(2,2);
1057	            auto S_B = Sparam(Box_B);
1058	            point.L[i][j] = S_B.get(1,1);
1059	            point.T[i][j] = S_B.get(2,1);
1060	            // no isolation measurement available
1061	            point.I[i][j] = 0.0;
1062	
1063	            // Reverse coefficients, will be handled in loop iteration where i=j and j=i
1064	        }
1065	    }
1066	    return point;
1067	}
