43	bool CalibrationMeasurement::Base::setStandard(CalStandard::Virtual *standard)
44	{
45	    if(standard) {
46	        if(supportedStandardTypes().count(standard->getType())) {
47	            // can use this standard
48	            this->standard = standard;
49	            connect(standard, &CalStandard::Virtual::deleted, this, [=](){
50	                setStandard(nullptr);
