161	void CalibrationMeasurement::Base::fromJSON(nlohmann::json j)
162	{
163	    if(j.contains("standard")) {
164	        auto standards = cal->getKit().getStandards();
165	        standard = nullptr;
166	        unsigned long long id = j.value("standard", 0ULL);
167	        for(auto s : standards) {
168	            if(s->getID() == id) {
169	                setStandard(s);
170	                break;
171	            }
172	        }
173	    }
