175	}
176	
177	bool CalibrationMeasurement::Base::canMeasureSimultaneously(std::set<CalibrationMeasurement::Base *> measurements)
178	{
179	    std::set<int> usedPorts;
180	    for(auto m : measurements) {
181	        std::vector<int> ports;
182	        switch(m->getType()) {
183	        case Type::Open:
184	        case Type::Short:
185	        case Type::Load:
186	        case Type::SlidingLoad:
187	        case Type::Reflect:
188	            // Uses one port
189	            ports.push_back(static_cast<OnePort*>(m)->getPort());
190	            break;
191	        case Type::Through:
192	        case Type::Line:
193	            // Uses two ports
194	            ports.push_back(static_cast<TwoPort*>(m)->getPort1());
195	            ports.push_back(static_cast<TwoPort*>(m)->getPort2());
196	            break;
197	        case Type::Isolation:
198	            // Uses all ports, unable to measure simultaneously
199	            if(measurements.size() > 1) {
200	                return false;
201	            }
202	            break;
203	        case Type::Last:
204	            // invalid
205	            return false;
206	        }
207	        for(auto p : ports) {
208	            if(usedPorts.count(p)) {
209	                // port already used for another measurement
210	                return false;
211	            } else {
212	                usedPorts.insert(p);
213	            }
214	        }
215	    }
216	    // if we get here, no port collisions occurred
217	    return true;
218	}
