236	            ret->setToolTip("No calibration standard assigned, unable to use this measurement");
237	        } else if(standard->minFrequency() > points.front().frequency || standard->maxFrequency() < points.back().frequency) {
238	            ret->setBackground(Qt::yellow);
239	            ret->setToolTip("Usable frequency range constrained by calibration standard to "+Unit::ToString(minUsableFreq(), "Hz", " kMG", 4)+" - "+Unit::ToString(maxUsableFreq(), "Hz", " kMG", 4));
240	        }
241	    }
242	    return ret;
243	}
