245	double CalibrationMeasurement::OnePort::minUsableFreq()
246	{
247	    if(points.size() > 0 && standard) {
248	        return max(points.front().frequency, standard->minFrequency());
249	    } else {
250	        return numeric_limits<double>::max();
251	    }
252	}
253	
254	double CalibrationMeasurement::OnePort::maxUsableFreq()
255	{
256	    if(points.size() > 0 && standard) {
257	        return min(points.back().frequency, standard->maxFrequency());
258	    } else {
259	        return 0;
260	    }
261	}
