269	void CalibrationMeasurement::OnePort::addPoint(const DeviceDriver::VNAMeasurement &m)
270	{
271	    QString measurementName = "S"+QString::number(port)+QString::number(port);
272	    if(m.measurements.count(measurementName) > 0) {
273	        Point p;
274	        p.frequency = m.frequency;
275	        p.S = m.measurements.at(measurementName);
276	        points.push_back(p);
277	        timestamp = QDateTime::currentDateTimeUtc();
278	    }
279	}
