281	QWidget *CalibrationMeasurement::OnePort::createSettingsWidget()
282	{
283	    auto label = new QLabel("Port:");
284	    auto cbPort = new QComboBox();
285	    auto dev = DeviceDriver::getActiveDriver();
286	    if(dev) {
287	        if(port == 0) {
288	            setPort(1);
289	        }
290	        for(unsigned int i=1;i<=dev->getInfo().Limits.VNA.ports;i++) {
291	            cbPort->addItem(QString::number(i));
292	            if(port == i) {
293	                cbPort->setCurrentText(QString::number(i));
294	            }
295	        }
296	    }
297	    if(port > 0 && cbPort->findText(QString::number(port)) < 0) {
298	        // set already selected port, even if device is not connected or does not have this port
299	        cbPort->addItem(QString::number(port));
300	        cbPort->setCurrentText(QString::number(port));
301	    }
302	    connect(cbPort, qOverload<int>(&QComboBox::currentIndexChanged), [=](){
303	        setPort(cbPort->currentText().toInt());
304	    });
305	    connect(this, &OnePort::portChanged, cbPort, [=](){
