1378	void VNA::DisableCalibration()
1379	{
1380	    cal.deactivate();
1381	}
1382	
1383	void VNA::ApplyCalibration(Calibration::CalType type)
1384	{
1385	    if(cal.canCompute(type)) {
1386	        try {
1387	            cal.compute(type);
1388	        } catch (runtime_error &e) {
1389	            InformationBox::ShowError("Calibration failure", e.what());
1390	            DisableCalibration();
1391	        }
1392	    } else {
1393	        if(settings.sweepType == SweepType::Frequency) {
1394	            // Not all required traces available
1395	            InformationBox::ShowMessageBlocking("Missing calibration measurements", "Not all calibration measurements for this type of calibration have been taken. The calibration can be enabled after the missing measurements have been acquired.");
1396	            DisableCalibration();
1397	            cal.edit(&traceModel);
1398	        } else {
1399	            // Not all required traces available
1400	            InformationBox::ShowMessageBlocking("Missing calibration measurements", "Not all calibration measurements for this type of calibration have been taken. Please switch to frequency sweep to take these measurements.");
1401	            DisableCalibration();
1402	        }
1403	    }
1404	}
1405	
1406	void VNA::StartCalibrationMeasurements(std::set<CalibrationMeasurement::Base*> m)
1407	{
1408	    if(!window->getDevice()) {
1409	        return;
1410	    }
1411	    // Stop sweep
1412	    running = false;
1413	    ConfigureDevice();
1414	    calMeasurements = m;
1415	    // Delete any already captured data of this measurement
1416	    cal.clearMeasurements(m);
1417	    calWaitFirst = true;
1418	    // show messagebox
1419	    QString text = "Measuring ";
1420	    if(m.size() == 1) {
1421	        text.append("\"");
1422	        text.append(CalibrationMeasurement::Base::TypeToString((*m.begin())->getType()));
1423	        text.append("\" parameters.");
1424	    } else {
1425	        text.append("multiple calibration standards.");
1426	    }
1427	    calDialog->setLabelText(text);
1428	
1429	    // Trigger sweep to start from beginning
1430	    running = true;
1431	    ConfigureDevice(true, [=](bool){
1432	        // enable calibration measurement only in transmission callback (prevents accidental sampling of data which was still being processed)
1433	        calMeasuring = true;
1434	    });
1435	}
