413	void Calibration::edit(TraceModel *traceModel)
414	{
415	    auto d = new QDialog();
416	    d->setAttribute(Qt::WA_DeleteOnClose);
417	    auto ui = new Ui::CalibrationDialog;
418	    ui->setupUi(d);
419	
420	    ui->calMinFreq->setUnit("Hz");
421	    ui->calMinFreq->setPrecision(4);
422	    ui->calMinFreq->setPrefixes(" kMG");
423	    ui->calMaxFreq->setUnit("Hz");
424	    ui->calMaxFreq->setPrecision(4);
425	    ui->calMaxFreq->setPrefixes(" kMG");
426	
427	    // generate all possible calibration with the connected device
428	    vector<CalType> availableCals = getAvailableCalibrations();
429	
430	    for(auto c : availableCals) {
431	        ui->calibrationList->addItem(c.getReadableDescription());
432	    }
433	
434	    auto updateCalStatistics = [=](){
435	        lock_guard<recursive_mutex> guard(access);
436	        ui->activeCalibration->setText(caltype.getReadableDescription());
437	        ui->calPoints->setValue(points.size());
438	        if(points.size() > 0) {
439	            ui->calMinFreq->setValue(points.front().frequency);
440	            ui->calMaxFreq->setValue(points.back().frequency);
441	        } else {
442	            ui->calMinFreq->setValue(0);
443	            ui->calMaxFreq->setValue(0);
444	        }
445	    };
446	
447	    auto updateCalButtons = [=](){
448	        lock_guard<recursive_mutex> guard(access);
449	        auto row = ui->calibrationList->currentRow();
450	        if(row < 0) {
451	            ui->activate->setEnabled(false);
452	            ui->deactivate->setEnabled(false);
453	        } else {
454	            if(caltype == availableCals[row]) {
455	                ui->deactivate->setEnabled(true);
456	                ui->activate->setEnabled(false);
457	            } else {
458	                ui->deactivate->setEnabled(false);
459	                ui->activate->setEnabled(canCompute(availableCals[row]));
460	            }
461	        }
462	    };
463	
464	    auto updateCalibrationList = [=](){
465	        auto style = QApplication::style();
466	        for(unsigned int i=0;i<availableCals.size();i++) {
467	            QIcon icon;
468	            if(canCompute(availableCals[i])) {
469	                icon = style->standardIcon(QStyle::SP_DialogApplyButton);
470	            } else {
471	                icon = style->standardIcon(QStyle::SP_MessageBoxCritical);
472	            }
473	            ui->calibrationList->item(i)->setIcon(icon);
474	        }
475	        updateCalButtons();
476	    };
477	
478	    updateCalibrationList();
479	    updateCalStatistics();
480	    updateCalButtons();
481	
482	    connect(ui->calibrationList, &QListWidget::doubleClicked, [=](const QModelIndex&) {
483	        ui->activate->clicked();
484	    });
485	
486	    connect(ui->calibrationList, &QListWidget::currentRowChanged, [=](){
487	        updateCalButtons();
488	    });
489	
490	    connect(this, &Calibration::activated, d, [=](){
491	        updateCalibrationList();
492	        updateCalStatistics();
493	        updateCalButtons();
494	    });
495	
496	    connect(this, &Calibration::deactivated, d, [=](){
497	        updateCalibrationList();
498	        updateCalStatistics();
499	        updateCalButtons();
500	    });
501	
502	    connect(ui->activate, &QPushButton::clicked, [=](){
503	        auto cal = availableCals[ui->calibrationList->currentRow()];
504	        compute(cal);
